create index if not exists kitchen_equipment_org_store_idx on public.kitchen_equipment(organization_id,store_id);
create index if not exists kitchen_equipment_station_idx on public.kitchen_equipment(station_id);
create index if not exists kitchen_equipment_updated_by_idx on public.kitchen_equipment(updated_by) where updated_by is not null;
create index if not exists station_routing_org_store_idx on public.station_routing_rules(organization_id,store_id);
create index if not exists station_routing_product_idx on public.station_routing_rules(product_id) where product_id is not null;
